import{_ as r,o as i,c as s,ah as A}from"./chunks/framework.CYVX1O9m.js";const l="data:image/png;base64,",c="/projects/Tonybot/en/latest/assets/image3.CNEufYWI.jpeg",d="/projects/Tonybot/en/latest/assets/image4.BS7RYPyL.png",p="/projects/Tonybot/en/latest/assets/image5.Dnu8e8vo.png",h="/projects/Tonybot/en/latest/assets/image6.pIL8Xlja.png",g="/projects/Tonybot/en/latest/assets/image7.CafyM_ts.png",m="/projects/Tonybot/en/latest/assets/image8.Cpk_f7bq.png",y="data:image/png;base64,",u="/projects/Tonybot/en/latest/assets/image10.BSJA08eG.png",b="/projects/Tonybot/en/latest/assets/image11.CID9cc74.png",w="/projects/Tonybot/en/latest/assets/image12.xgmfWlR3.png",f="/projects/Tonybot/en/latest/assets/image13.D33dfF-H.png",z="/projects/Tonybot/en/latest/assets/image14.BJwcZa6W.png",I="/projects/Tonybot/en/latest/assets/image15.BVXNT69l.png",E="/projects/Tonybot/en/latest/assets/image16.D144H71D.png",V="/projects/Tonybot/en/latest/assets/image17.CZB5mi4U.png",C="/projects/Tonybot/en/latest/assets/image18.BAQ0oV8A.png",T="/projects/Tonybot/en/latest/assets/image19.B70PgWAM.png",Q="/projects/Tonybot/en/latest/assets/image20.DKeDxsi6.png",R="/projects/Tonybot/en/latest/assets/image21.DaP14Jlo.png",e="/projects/Tonybot/en/latest/assets/image22.LVyDZzaC.png",o="data:image/png;base64,",n="data:image/png;base64,",a="/projects/Tonybot/en/latest/assets/image25.CRyXjHcG.png",q="/projects/Tonybot/en/latest/assets/image26.CzSTE9if.png",G="/projects/Tonybot/en/latest/assets/image27.D8xAXC2A.png",N="data:image/png;base64,",B="data:image/png;base64,",S=JSON.parse('{"title":"2. APP Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.app_control.md","filePath":"docs/2.app_control.md"}'),P={name:"docs/2.app_control.md"};function U(O,t,K,X,v,Y){return i(),s("div",null,[...t[0]||(t[0]=[A('<h1 id="_2-app-control" tabindex="-1">2. APP Control <a class="header-anchor" href="#_2-app-control" aria-label="Permalink to &quot;2. APP Control&quot;">​</a></h1><p><strong>Tonybot comes with the app control program already pre-installed, so you can start using it right away.</strong></p><h2 id="_2-1-app-installation" tabindex="-1">2.1 App Installation <a class="header-anchor" href="#_2-1-app-installation" aria-label="Permalink to &quot;2.1 App Installation&quot;">​</a></h2><p>For iOS users: Simply download <a href="https://apps.apple.com/us/app/wonderbot-robot/id1519146341" target="_blank" rel="noreferrer">Wonderbot</a> from the App Store.</p><p>For Android users: Download &quot;<strong>Wonderbot</strong>&quot; from the Google Play Store using this link: <a href="https://play.google.com/store/apps/details?id=com.Wonder.bot" target="_blank" rel="noreferrer">https://play.google.com/store/apps/details?id=com.Wonder.bot</a></p><h2 id="_2-2-app-connection" tabindex="-1">2.2 App Connection <a class="header-anchor" href="#_2-2-app-connection" aria-label="Permalink to &quot;2.2 App Connection&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>Before using the app, ensure that Bluetooth and location services are enabled in your phone&#39;s settings.</p></li><li><p>Pair the device using the Bluetooth button within the app. Do not attempt to pair it through your phone&#39;s settings with a passkey.</p></li></ul></section><p>(1) Turn ON the robot.</p><p>(2) Open the Wonderbot app and tap-on <img loading="lazy" height="78" width="87" src="'+l+'" style="width:70px;"> and select Tonybot from the available robot models.</p><img loading="lazy" height="571" width="1220" class="common_img" src="'+c+'"><p>(3) Once you&#39;re in the game control interface, tap the flashing Bluetooth icon <img loading="lazy" height="97" width="87" src="'+d+'" style="width:70px;"> and select Tonybot from the list to complete the connection.</p><img loading="lazy" height="571" width="1219" class="common_img" src="'+p+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If you can&#39;t find the device, tap the Search button to locate it.</p></section><p>(4) Once the connection is successful, the Bluetooth icon will stay lit, and the battery level will be shown on the left side.</p><img loading="lazy" height="594" width="1269" class="common_img" src="'+h+'"><h2 id="_2-3-feature-overview" tabindex="-1">2.3 Feature Overview <a class="header-anchor" href="#_2-3-feature-overview" aria-label="Permalink to &quot;2.3 Feature Overview&quot;">​</a></h2><p>The app enables you to control Tonybot&#39;s movements, ultrasonic obstacle avoidance, ultrasonic following, action groups, and the <strong>&quot;Reset&quot;</strong> function, all with a simple tap of a button.</p><p>The interface is organized into two sections, as illustrated in the image below:</p><img loading="lazy" height="591" width="1265" class="common_img" src="'+g+'"><p>(1) Menu Bar</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Description</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="94" width="116" src="'+m+'"></td><td style="text-align:center;">Return to the main interface to select the robot model</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="29" width="97" src="'+y+'"></td><td style="text-align:center;">Displays Tonybot&#39;s current battery level in real-time</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="93" width="108" src="'+u+'"></td><td style="text-align:center;">Camera feed: View the live video stream from the ESP32 camera.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="94" width="116" src="'+b+'"></td><td style="text-align:center;">Bluetooth connection: The icon flashes when disconnected and stays solid once connected.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="94" width="116" src="'+w+'"></td><td style="text-align:center;">More information</td></tr></tbody></table><p>(2) Control Zone</p><table class="docutils-nobg" style="margin:0 auto;" border="1"><colgroup><col><col></colgroup><tbody><tr><td><strong>Icon</strong></td><td><strong>Description</strong></td></tr><tr><td><img loading="lazy" height="172" width="173" src="'+f+'"></td><td>Control Tonybot&#39;s movement</td></tr><tr><td><img loading="lazy" height="156" width="260" src="'+z+'"></td><td>View ultrasonic distance while in obstacle avoidance mode</td></tr><tr><td><img loading="lazy" height="86" width="106" src="'+I+'"></td><td>Turn the ultrasonic obstacle avoidance feature on or off</td></tr><tr><td><img loading="lazy" height="87" width="95" src="'+E+'"></td><td>Enable or disable the ultrasonic following feature</td></tr><tr><td><img loading="lazy" height="97" width="96" src="'+V+'"></td><td>Switch the ultrasonic RGB lights on or off</td></tr><tr><td><img loading="lazy" height="45" width="235" src="'+C+'"></td><td>Adjust the color of the ultrasonic RGB lights</td></tr><tr><td><img loading="lazy" height="164" width="216" src="'+T+'"></td><td><strong>Tap to trigger an action group on Tonybot.</strong><br> (This includes both preset and custom action groups.)</td></tr><tr><td><img loading="lazy" height="193" width="260" src="'+Q+'"></td><td>Control Tonybot&#39;s rotation in place</td></tr><tr><td><img loading="lazy" height="81" width="170" src="'+R+'"></td><td>Reset Tonybot&#39;s pose</td></tr></tbody></table><h2 id="_2-4-app-control-program-download-optional" tabindex="-1">2.4 App Control Program Download (Optional) <a class="header-anchor" href="#_2-4-app-control-program-download-optional" aria-label="Permalink to &quot;2.4 App Control Program Download (Optional)&quot;">​</a></h2><p><a href="../_static/source_code/main.zip">mian.py</a></p><p>Tonybot comes pre-installed with the app control program. If you download other custom programs, the app control functionality will be overwritten. To restore the app control feature, you can use one of the following methods:</p><h3 id="_2-4-1-restore-program" tabindex="-1"><strong>2.4.1 Restore Program</strong> <a class="header-anchor" href="#_2-4-1-restore-program" aria-label="Permalink to &quot;**2.4.1 Restore Program**&quot;">​</a></h3><p>The default factory program includes a self-recovery feature. To restore the app control, simply use the Python editor to connect to the device, delete the <strong>&quot;main.py&quot;</strong> program, and restart the device. Follow these steps:</p><p>(1) Open the <strong>Hiwonder Python Editor</strong> software.<img loading="lazy" height="97" width="78" src="'+e+'" style="width:70px;">；</p><p>(2) Click the Connect button <img loading="lazy" height="76" width="84" src="'+o+'" style="width:70px;"> in the menu. Once the connection is established, the icon will turn green <img loading="lazy" height="77" width="79" src="'+n+'" style="width:70px;">.</p><img loading="lazy" height="330" width="880" class="common_img" src="'+a+'"><p>(3) In the <strong>&quot;Device (Connected)&quot;</strong> section, right-click the <strong>&quot;main.py&quot;</strong> file and select <strong>Delete</strong>. Afterward, restart the device to complete the process.</p><img loading="lazy" height="334" width="779" class="common_img" src="'+q+'"><h3 id="_2-4-2-redownload-the-app-control-program" tabindex="-1">2.4.2 Redownload the App Control Program <a class="header-anchor" href="#_2-4-2-redownload-the-app-control-program" aria-label="Permalink to &quot;2.4.2 Redownload the App Control Program&quot;">​</a></h3><p>(1) Open the <strong>Hiwonder Python Editor</strong> software <img loading="lazy" height="97" width="78" src="'+e+'" style="width:70px;">.</p><p>(2) Click the <strong>Connect</strong> button <img loading="lazy" height="76" width="84" src="'+o+'" style="width:70px;"> in the menu. The icon will turn green once the connection is successfully established <img loading="lazy" height="77" width="79" src="'+n+'" style="width:70px;">.</p><img loading="lazy" height="330" width="880" class="common_img" src="'+a+'"><p>(3) Drag the <strong>&quot;main.py&quot;</strong> file into the Python editor.</p><img loading="lazy" height="436" width="1119" class="common_img" src="'+G+'"><p>(4) Click <img loading="lazy" height="64" width="68" src="'+N+'" style="width:70px;"> to download the program to the device. After the download is complete, restart the device to finalize the process.</p><img loading="lazy" height="88" width="475" class="common_img" src="'+B+'">',41)])])}const j=r(P,[["render",U]]);export{S as __pageData,j as default};
